SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.abbr AS oblname, Имена_станций.ordnumb, Станции2004.YEAR, Станции2004.NUST, Станции2004.E, Станции2004.EOTP, Станции2004.EURT, Станции2004.EUST, Станции2004.Q, Станции2004.TURT, Станции2004.TUST, Станции2004.B, Станции2004.GAZ, Доп_угли2004.gazpp, Станции2004.MAZUT, Станции2004.TORF, Станции2004.SLAN, Станции2004.GTT, Станции2004.PROCH, Станции2004.UGOL, Станции2004.DON, Станции2004.PODM, Станции2004.PECH, Доп_угли2004.int, Доп_угли2004.vork, Станции2004.ARKT, Станции2004.KUZN, Станции2004.URAL, Доп_угли2004.sver, Доп_угли2004.chel, Доп_угли2004.kizel, Станции2004.BASHK, Станции2004.EKIB, Станции2004.KARAG, Станции2004.KAN, Доп_угли2004.nazar, Доп_угли2004.ibor, Доп_угли2004.berez, Доп_угли2004.per, Станции2004.IRKUT, Доп_угли2004.azey, Доп_угли2004.cher, Доп_угли2004.jer, Станции2004.HAK, Станции2004.TUV, Станции2004.BUR, Доп_угли2004.gusin, Доп_угли2004.tugn, Станции2004.CHIT, Доп_угли2004.har, Доп_угли2004.urt, Станции2004.YAKUT AS Выражение1, Станции2004.AMUR AS Выражение2, Станции2004.URG, Станции2004.PRIM, Станции2004.LUCH, Станции2004.MAG, Станции2004.SAH, Станции2004.USHUM, Станции2004.QOTR, Станции2004.SNK, Станции2004.EWTP, Станции2004.NT, Станции2004.OBOR, Станции2004.VED, Станции2004.OBL, Станции2004.DEP, Станции2004.OES, Станции2004.ER, Станции2004.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм
FROM (((Станции2004 INNER JOIN Имена_станций ON Станции2004.NUMB1120=Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON Станции2004.OES=Имена_ОЭС.oes) INNER JOIN Имена_областей ON Станции2004.OBL=Имена_областей.OBL) LEFT JOIN Доп_угли2004 ON (Станции2004.NUMB1120=Доп_угли2004.NUMB1120) AND (Станции2004.YEAR=Доп_угли2004.YEAR);
